// Review layout only. Raster artwork is generated by image_gen and never painted here.
const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto');
const sharp = require(process.env.RL_SHARP_MODULE || 'sharp');
const out = __dirname, root = path.resolve(out, '../../..');
const read = p => JSON.parse(fs.readFileSync(p, 'utf8').replace(/^\uFEFF/, ''));
const hash = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const review = read(path.join(out, 'review.json'));
const c = review.candidates[0];
const accepted = read(path.join(out, '../skill-icon-review-32/review.json')).candidates.filter(a => a.id !== 'A02');
const mini = accepted.map(a => `<div><img src="../skill-icon-review-32/${a.files[32].file}" width="32" height="32" alt="${a.title}"><span>${a.number} · ${a.title}</span></div>`).join('');
fs.writeFileSync(path.join(out, 'index.html'), `<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IC33 · Déflagration occulte</title>
<style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#0b1017;color:#e1e7ec;font:15px Segoe UI,Arial}main{max-width:730px;margin:auto}h1{font-size:25px;margin:8px 0 12px}p{line-height:1.6;color:#a6b6c5}small{color:#b6a8ff}article{padding:22px;background:#111923;border:1px solid #3a4654;border-radius:10px;max-width:480px;margin:24px auto}h2{font-size:18px;margin:0 0 20px;text-align:center}.large{display:grid;justify-items:center;gap:10px}.large img{width:128px;height:128px}.native{display:flex;justify-content:center;gap:48px;align-items:end;margin:28px 0 4px}.native>div{display:grid;justify-items:center;gap:10px}span{color:#a6b6c5;font-size:12px}img{display:block;max-width:none}.kept{border-top:1px solid #293543;margin-top:25px;padding-top:16px;display:flex;flex-wrap:wrap;gap:16px 25px}.kept>div{display:flex;align-items:center;gap:8px}footer{font-size:12px;line-height:1.8;margin:22px 0;color:#a6b6c5}a{color:#d7cef4}@media(max-width:480px){body{padding:16px}.native{gap:30px}}</style>
<main><small>SKILLS-IC33 · PROPOSITION 60 · A02-C02</small><h1>Déflagration occulte</h1><p>Une explosion d’énergie occulte. Nouvelle proposition à examiner à taille réelle.</p><article id="A02-C02"><h2>60 · Déflagration occulte</h2><div class="large"><img src="${c.files[128].file}" width="128" height="128" alt="Nouvelle explosion occulte"><span>128 px · détail du dessin</span></div><div class="native">${[32,64,24].map(s=>`<div><img src="${c.files[s].file}" width="${s}" height="${s}" alt="Explosion occulte ${s} px"><span>${s} px</span></div>`).join('')}</div></article><p>Les cinq autres icônes restent validées :</p><div class="kept">${mini}</div><footer>Vues à taille réelle, sans agrandissement des petits exports.<br>Proposition 60 en attente de validation visuelle. Textes et règles inchangés.<br><a href="prompts/A02-C02.txt">Prompt · génération intégrée image_gen</a> · <a href="../skill-icon-review-32/index.html">Revue précédente</a></footer></main></html>`);
const img = (f,x,y,s) => `<image x="${x}" y="${y}" width="${s}" height="${s}" href="data:image/png;base64,${fs.readFileSync(path.join(out,f)).toString('base64')}"/>`;
const pieces = ['<rect width="540" height="410" fill="#0b1017"/>','<text x="24" y="34" font-size="21" fill="#e1e7ec">60 · Déflagration occulte</text>','<text x="24" y="60" font-size="13" fill="#b6a8ff">A02-C02 · Nouvelle proposition</text>',img(c.files[128].file,206,82,128)];
for (const [s,x] of [[32,146],[64,246],[24,386]]) pieces.push(img(c.files[s].file,x,270-s,s),`<text x="${x+s/2}" y="294" text-anchor="middle" font-size="13" fill="#a6b6c5">${s} px</text>`);
pieces.push('<text x="24" y="354" font-size="13" fill="#a6b6c5">Vues natives · explosion occulte seule</text>','<text x="24" y="384" font-size="12" fill="#a6b6c5">En attente de validation du dessin.</text>');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="540" height="410"><g font-family="Segoe UI,Arial">${pieces.join('')}</g></svg>`;
fs.writeFileSync(path.join(out, 'native-review-board.svg'), svg);
async function main() {
  await sharp(Buffer.from(svg)).png().toFile(path.join(out, 'native-review-board.png'));
  for (const f of review.protected_hashes) if (hash(path.resolve(root,f.file)) !== f.sha256) throw Error('Protected file changed: '+f.file);
  const validation = read(path.join(out, 'validation.json'));
  validation.native_review_board = {width:540,height:410};
  validation.other_five_IC32_drawings_preserved = true;
  validation.only_new_candidate = '60 A02-C02';
  fs.writeFileSync(path.join(out,'validation.json'),JSON.stringify(validation,null,2)+'\n');
  fs.writeFileSync(path.join(out,'README.md'),'# IC33 · Déflagration occulte\n\nProposition 60 `A02-C02`, non intégrée. Direction demandée : « dessine juste une explosion occulte :) ».\n\nGénération intégrée `image_gen.imagegen`, prompt exact dans `prompts/A02-C02.txt`. Source copiée dans `A02-C02-master.png`. Redimensionnement Lanczos uniquement ; aucune retouche du dessin par code.\n\nVues 128, 32, 64 et 24 px dans `index.html` ; planche `native-review-board.png`. Les cinq autres dessins IC32 restent validés et inchangés.\n\nLe premier essai avec sceau, généré avant la précision du joueur, est abandonné. Aucun accord sur ce dessin ou celui-ci ne sera déduit de l’accord sur la direction seule.\n');
  console.log(JSON.stringify({candidate:'60 A02-C02',protected_hashes_preserved:review.protected_hashes.length}));
}
main().catch(e=>{console.error(e);process.exitCode=1;});
